 BEGIN PERFORM delete_whole_trips_v1(ARRAY[one],'00000000-0000-4000-8000-000000000002');RAISE EXCEPTION 'Staff deletion succeeded';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM delete_whole_trips_v1(ARRAY[one,two],a);RAISE EXCEPTION 'Financial deletion succeeded';EXCEPTION WHEN SQLSTATE '55000' THEN NULL;END;
 IF (SELECT count(*) FROM trips)<>3 OR (SELECT count(*) FROM trip_stops)<>3 OR (SELECT count(*) FROM trip_line_items)<>2 OR EXISTS(SELECT FROM transaction_deletion_jobs) THEN RAISE EXCEPTION 'Failed batch did not roll back'; END IF;
