 IF (SELECT count(*) FROM trips)<>2 OR (SELECT count(*) FROM trip_stops)<>1 THEN RAISE EXCEPTION 'Unrelated trips/stops changed'; END IF;
 IF jsonb_array_length(delete_whole_trips_v1(ARRAY[one],a))<>2 THEN RAISE EXCEPTION 'Duplicate request not idempotent'; END IF;
 IF has_function_privilege('authenticated','delete_whole_trips_v1(uuid[],uuid)','EXECUTE') OR NOT has_function_privilege('service_role','delete_whole_trips_v1(uuid[],uuid)','EXECUTE') THEN RAISE EXCEPTION 'RPC exposed'; END IF;
END $$;
